  naturalExtinctionRate: number;    // 1.0 baseline (10 extinctions per million species-years)
  extinctionAcceleration: number;   // Rate of change

  // === HABITAT LOSS ===
  habitatLossPercent: number;       // [0, 100] % habitat destroyed
