  // === MONTREAL PROTOCOL SUCCESS ===
  cfcPhaseOutPercent: number;          // [0, 100] % CFCs eliminated
  halonPhaseOutPercent: number;        // [0, 100] % halons eliminated
  complianceRate: number;              // [0, 1] International compliance
