    console.log(`   Boundary: ${intervention.tippingPoint}`);
    console.log(`   Type: ${intervention.type}`);
    console.log(`   Reduction: ${(reduction * 100).toFixed(0)}% (${boundary.currentValue.toFixed(2)} → ${(boundary.currentValue - reduction).toFixed(2)})`);
