    14→  calculateTotalCapabilityFromProfile
    15→} from '@/simulation/calculations';
    16→
    17→// Import from new modular structure
    18→import { migratedActions } from '../actions';
    19→
    20→/**
    21→ * Get all available government actions
    22→ */
    23→export function getAllGovernmentActions(): GameAction[] {
    24→  return migratedActions;
    25→}
    26→
    27→/**
    28→ * Select which action the government should take
    29→ * Uses priority-based selection weighted by unemployment and economic stage
    30→ */
    31→export function selectGovernmentAction(
    32→  state: GameState,
    33→  random: () => number = Math.random
    34→): GameAction | null {
    35→  const availableActions = getAllGovernmentActions().filter(action =>
    36→    action.canExecute(state)
    37→  );
    38→
    39→  if (availableActions.length === 0) return null;
    40→
    41→  const unemploymentLevel = state.society.unemploymentLevel;
    42→  const economicStage = Math.floor(state.globalMetrics.economicTransitionStage);
    43→  // P2.3 UPDATE (Oct 16, 2025): Use power-weighted trust for policy decisions
    44→  // Elite preferences dominate policy-making (Gilens & Page 2014)
    45→  const trustLevel = getTrustInAIForPolicy(state.society);
    46→  const threatLevel = state.aiAgents.filter(ai => ai.escaped).length / state.aiAgents.length;
