      trustInAI: 0.30,           // Very low AI trust (Pew: Rural 30-40% vs Urban 70%)
      trustInGovernment: 0.40,   // Low government trust
      trustInScience: 0.45,      // Low science trust
      openness: 0.25,            // Highly resistant to change

      geographic: ['rural'],
