     2→ * Breakthrough Technology System
     3→ * 
     4→ * Represents major technological breakthroughs that can:
     5→ * - Reverse environmental damage
     6→ * - Prevent/resolve social crises
     7→ * - Enable sustainable abundance
     8→ * 
     9→ * Part of Utopian Dynamics Phase 2
    10→ */
    11→
    12→export interface TechnologyNode {
    13→  id: string;
    14→  name: string;
    15→  category: 'environmental' | 'social' | 'medical' | 'infrastructure';
    16→  
    17→  // Status
    18→  unlocked: boolean;
    19→  researchProgress: number; // 0-1
    20→  deploymentLevel: number; // 0-1 (how widely deployed)
    21→  
    22→  // Unlock requirements
    23→  requirements: {
    24→    minAICapability: number;
    25→    minEconomicStage: number;
    26→    requiredInvestment: number; // Total $B needed
    27→    prerequisiteTechs: string[]; // Must unlock these first
    28→    blockedByCrises?: string[]; // Can't research during these crises
    29→  };
    30→  
