     1→/**
     2→ * TIER 1.7.4: Nuclear Winter System
     3→ * 
     4→ * Models the long-term catastrophic effects of nuclear war.
     5→ * 
     6→ * Research backing:
     7→ * - Carl Sagan et al. (1983): "Nuclear Winter" original paper
     8→ * - Robock & Toon (2012): "Local Nuclear War, Global Suffering"
     9→ *   - 100 15-kt weapons (India-Pakistan scale) → 5 Tg soot
    10→ *   - Temperature drops 1.25°C globally for 10 years
    11→ *   - 2 billion people at risk of starvation
    12→ * - Coupe et al. (2019): Full-scale US-Russia war
    13→ *   - 150 Tg soot into stratosphere
    14→ *   - Temperature drops 15-20°C
    15→ *   - Crop yields drop to 10% of normal
    16→ *   - 90% of Northern Hemisphere population dies
    17→ *   - Recovery takes 5-10 years
    18→ * 
    19→ * Implementation philosophy:
    20→ * - Nuclear war is already catastrophic (1-2B immediate deaths)
    21→ * - Nuclear winter makes it apocalyptic (additional 4-6B starvation deaths)
    22→ * - This is WHY nuclear war = extinction, not just the blast
    23→ */
    24→
    25→import { GameState } from '../types/game';
    26→import { NuclearWinterState, RadiationZone } from '../types/nuclearWinter';
    27→import { addAcuteCrisisDeaths } from './populationDynamics';
    28→
    29→/**
    30→ * Initialize nuclear winter state (inactive by default)
    31→ */
    32→export function initializeNuclearWinterState(): NuclearWinterState {
    33→  return {
    34→    active: false,
    35→    triggerMonth: -1,
    36→    
    37→    // Atmospheric
    38→    sootInStratosphere: 0,
    39→    sootDecayRate: 0.05,  // 5% per month (research: ~3-7 year half-life)
    40→    currentSoot: 0,
    41→    
    42→    // Climate
    43→    temperatureAnomaly: 0,
    44→    baselineTemperature: 15.0,  // °C global average (pre-war)
    45→    
    46→    // Agriculture
    47→    cropYieldMultiplier: 1.0,   // Normal initially
    48→    monthlyStarvationRate: 0,
    49→    
    50→    // Radiation
    51→    radiationZones: [],
    52→    
    53→    // Duration
    54→    monthsSinceWar: 0,
    55→    peakMortalityMonths: 24,    // Peak starvation lasts 2 years
    56→    recoveryStartMonth: 24,
    57→    
    58→    // Deaths
    59→    totalWinterDeaths: 0,
    60→    totalRadiationDeaths: 0
    61→  };
    62→}
    63→
    64→/**
    65→ * Trigger nuclear winter when nuclear war occurs
    66→ * 
    67→ * @param state - Game state
    68→ * @param warScale - Number of warheads exchanged (determines soot)
    69→ * @param targetCountries - Countries that were hit (for radiation zones)
    70→ */
    71→export function triggerNuclearWinter(
    72→  state: GameState,
    73→  warScale: number,
    74→  targetCountries: string[]
    75→): void {
    76→  const winter = state.nuclearWinterState;
    77→  
    78→  // Already in nuclear winter? Add to existing soot
    79→  if (winter.active) {
    80→    console.log(`\n⚠️  ADDITIONAL NUCLEAR EXCHANGE during existing nuclear winter`);
    81→    winter.sootInStratosphere += calculateSootInjection(warScale);
    82→    winter.currentSoot = winter.sootInStratosphere;
    83→    
    84→    // Add new radiation zones
    85→    addRadiationZones(winter, targetCountries, state.currentMonth);
    86→    return;
    87→  }
    88→  
    89→  // First nuclear war - activate nuclear winter
    90→  winter.active = true;
    91→  winter.triggerMonth = state.currentMonth;
    92→  winter.monthsSinceWar = 0;
    93→  
    94→  // Calculate soot injection based on war scale
    95→  winter.sootInStratosphere = calculateSootInjection(warScale);
    96→  winter.currentSoot = winter.sootInStratosphere;
    97→  
    98→  // Calculate initial temperature drop
    99→  winter.temperatureAnomaly = calculateTemperatureAnomaly(winter.currentSoot);
   100→  
   101→  // Calculate crop failure
   102→  winter.cropYieldMultiplier = calculateCropYield(winter.temperatureAnomaly);
   103→  
   104→  // Calculate starvation rate
   105→  winter.monthlyStarvationRate = calculateStarvationRate(
   106→    winter.cropYieldMultiplier,
   107→    winter.monthsSinceWar
   108→  );
   109→  
   110→  // Add radiation zones for hit countries
   111→  addRadiationZones(winter, targetCountries, state.currentMonth);
   112→  
   113→  console.log(`\n☢️  NUCLEAR WINTER TRIGGERED (Month ${state.currentMonth})`);
   114→  console.log(`   Soot injected: ${winter.sootInStratosphere.toFixed(0)} Tg`);
   115→  console.log(`   Temperature drop: ${winter.temperatureAnomaly.toFixed(1)}°C`);
   116→  console.log(`   Crop yield: ${(winter.cropYieldMultiplier * 100).toFixed(0)}% of normal`);
   117→  console.log(`   Starvation rate: ${(winter.monthlyStarvationRate * 100).toFixed(1)}% per month`);
   118→  console.log(`   Radiation zones: ${winter.radiationZones.length} countries`);
   119→  console.log(`   Expected duration: ${winter.recoveryStartMonth} months to recovery`);
   120→}
   121→
   122→/**
   123→ * Calculate soot injection based on war scale
   124→ * 
   125→ * Research (Robock & Toon 2012, Coupe et al. 2019):
   126→ * - Regional war (India-Pakistan, 100 warheads): 5 Tg
   127→ * - US-Russia limited (1000 warheads): 50 Tg
   128→ * - US-Russia full-scale (5000+ warheads): 150 Tg
   129→ * 
   130→ * @param warScale - Number of warheads exchanged
   131→ * @returns Soot in Teragrams
   132→ */
   133→function calculateSootInjection(warScale: number): number {
   134→  // Research-based scaling:
   135→  // - 100 warheads → 5 Tg
   136→  // - 1000 warheads → 50 Tg
   137→  // - 5000+ warheads → 150 Tg (saturation)
   138→  
   139→  if (warScale <= 100) {
   140→    return warScale * 0.05;  // 5 Tg per 100 warheads
   141→  } else if (warScale <= 1000) {
   142→    return 5 + (warScale - 100) * 0.05;  // Linear scaling
   143→  } else {
   144→    // Saturation: diminishing returns above 1000 warheads
   145→    return 50 + Math.min(100, (warScale - 1000) * 0.1);
   146→  }
   147→}
   148→
   149→/**
   150→ * Calculate temperature anomaly from soot level
   151→ * 
   152→ * Research (Robock & Toon 2012):
   153→ * - 5 Tg soot → -1.25°C
   154→ * - 50 Tg soot → -7°C
   155→ * - 150 Tg soot → -15 to -20°C
   156→ * 
   157→ * @param soot - Soot in stratosphere (Tg)
   158→ * @returns Temperature anomaly (negative °C)
   159→ */
   160→function calculateTemperatureAnomaly(soot: number): number {
   161→  if (soot <= 5) {
   162→    return -soot * 0.25;  // Linear: 5 Tg → -1.25°C
   163→  } else if (soot <= 50) {
   164→    return -1.25 - ((soot - 5) * 0.13);  // 50 Tg → -7°C
   165→  } else {
   166→    // Saturation: 150 Tg → -15 to -20°C
   167→    return -7 - Math.min(13, (soot - 50) * 0.13);
   168→  }
   169→}
   170→
   171→/**
   172→ * Calculate crop yield from temperature anomaly
   173→ * 
   174→ * Research: Each 1°C drop reduces crop yield by 5-10%
   175→ * At -15°C, crops fail almost entirely (90% reduction)
   176→ * 
   177→ * @param tempAnomaly - Temperature drop (negative °C)
   178→ * @returns Crop yield multiplier [0,1]
   179→ */
   180→function calculateCropYield(tempAnomaly: number): number {
   181→  // Each degree drop reduces yield by 7% (conservative mid-range)
   182→  const yieldLoss = Math.abs(tempAnomaly) * 0.07;
   183→  return Math.max(0.05, 1.0 - yieldLoss);  // Minimum 5% yield (some crops survive)
   184→}
   185→
   186→/**
   187→ * Calculate monthly starvation rate
   188→ * 
   189→ * Research (Robock & Toon 2012):
   190→ * - Peak starvation: Months 6-24 after war
   191→ * - 5% monthly mortality during peak
   192→ * - Gradual decline as crops partially recover
   193→ * 
   194→ * @param cropYield - Crop yield multiplier [0,1]
   195→ * @param monthsSinceWar - Months since nuclear war
   196→ * @returns Monthly starvation rate [0,1]
   197→ */
   198→function calculateStarvationRate(cropYield: number, monthsSinceWar: number): number {
   199→  // Food shortage severity (1 - crop yield)
   200→  const shortage = 1 - cropYield;
   201→  
   202→  // Starvation ramps up over first 6 months (takes time for food stocks to run out)
   203→  let rampMultiplier = 1.0;
   204→  if (monthsSinceWar < 6) {
   205→    rampMultiplier = monthsSinceWar / 6;  // Linear ramp: 0 → 1.0 over 6 months
   206→  }
   207→  
   208→  // Peak starvation: months 6-24
   209→  // After month 24, gradual decline as agriculture partially recovers
   210→  let recoveryMultiplier = 1.0;
   211→  if (monthsSinceWar > 24) {
   212→    // Exponential decay: 50% reduction every 24 months
   213→    recoveryMultiplier = Math.pow(0.5, (monthsSinceWar - 24) / 24);
   214→  }
   215→  
   216→  // Base starvation rate scales with shortage severity
   217→  // Research: 90% crop failure → 5% monthly mortality
   218→  const baseRate = shortage * 0.055;  // 90% shortage → 5% monthly
   219→  
   220→  return baseRate * rampMultiplier * recoveryMultiplier;
   221→}
   222→
   223→/**
   224→ * Add radiation zones for countries hit by nuclear weapons
   225→ */
   226→function addRadiationZones(
   227→  winter: NuclearWinterState,
   228→  countries: string[],
   229→  currentMonth: number
   230→): void {
   231→  countries.forEach(country => {
   232→    // Check if country already has radiation zone (multiple hits)
   233→    const existing = winter.radiationZones.find(z => z.country === country);
   234→    if (existing) {
   235→      // Increase intensity (multiple strikes)
   236→      existing.intensity = Math.min(1.0, existing.intensity + 0.3);
   237→      existing.currentLevel = existing.intensity;
   238→      return;
   239→    }
   240→    
   241→    // Add new radiation zone
   242→    winter.radiationZones.push({
   243→      country,
   244→      hitMonth: currentMonth,
   245→      intensity: 0.8,  // High radiation (0.8/1.0)
   246→      decayRate: 0.05,  // 5% per month (half-life ~14 months)
   247→      currentLevel: 0.8,
   248→      monthlyDeathRate: 0.01  // 1% additional monthly mortality
   249→    });
   250→  });
   251→}
   252→
   253→/**
   254→ * Update nuclear winter state each month
   255→ * 
   256→ * @param state - Game state
   257→ */
   258→export function updateNuclearWinter(state: GameState): void {
   259→  const winter = state.nuclearWinterState;
   260→  if (!winter.active) return;
   261→  
   262→  winter.monthsSinceWar++;
   263→  
   264→  // 1. Update soot levels (decay over time)
   265→  winter.currentSoot = winter.currentSoot * (1 - winter.sootDecayRate);
   266→  
   267→  // 2. Update temperature (recovers as soot clears)
   268→  winter.temperatureAnomaly = calculateTemperatureAnomaly(winter.currentSoot);
   269→  
   270→  // 3. Update crop yields (improve as temperature recovers)
   271→  winter.cropYieldMultiplier = calculateCropYield(winter.temperatureAnomaly);
   272→  
   273→  // 4. Update starvation rate
   274→  winter.monthlyStarvationRate = calculateStarvationRate(
   275→    winter.cropYieldMultiplier,
   276→    winter.monthsSinceWar
   277→  );
   278→  
   279→  // 5. Apply starvation deaths
   280→  if (winter.monthlyStarvationRate > 0) {
   281→    const population = state.humanPopulationSystem.population;
   282→    const starvationDeaths = population * winter.monthlyStarvationRate;
   283→    
   284→    if (starvationDeaths > 0.001) {  // Only log if > 1 million deaths
   285→      addAcuteCrisisDeaths(state, starvationDeaths, 'famine');
   286→      winter.totalWinterDeaths += starvationDeaths;
   287→      
   288→      // Log significant events
   289→      if (winter.monthsSinceWar % 12 === 0 || winter.monthsSinceWar === 6) {
   290→        console.log(`\n☢️  NUCLEAR WINTER (Month ${state.currentMonth}, ${winter.monthsSinceWar} months since war)`);
   291→        console.log(`   Soot remaining: ${winter.currentSoot.toFixed(1)} Tg (${(winter.currentSoot / winter.sootInStratosphere * 100).toFixed(0)}% of peak)`);
   292→        console.log(`   Temperature: ${winter.temperatureAnomaly.toFixed(1)}°C below baseline`);
   293→        console.log(`   Crop yield: ${(winter.cropYieldMultiplier * 100).toFixed(0)}%`);
   294→        console.log(`   Starvation: ${(starvationDeaths * 1000).toFixed(1)}M deaths this month`);
   295→        console.log(`   Total winter deaths: ${(winter.totalWinterDeaths * 1000).toFixed(0)}M`);
   296→      }
   297→    }
   298→  }
   299→  
   300→  // 6. Update radiation zones
   301→  updateRadiationZones(state, winter);
   302→  
   303→  // 7. Check if nuclear winter is over (soot cleared, starvation negligible)
   304→  if (winter.currentSoot < 0.5 && winter.monthlyStarvationRate < 0.001) {
   305→    winter.active = false;
   306→    console.log(`\n✅ NUCLEAR WINTER ENDED (Month ${state.currentMonth})`);
   307→    console.log(`   Duration: ${winter.monthsSinceWar} months (${(winter.monthsSinceWar / 12).toFixed(1)} years)`);
   308→    console.log(`   Total deaths: ${(winter.totalWinterDeaths * 1000).toFixed(0)}M starvation + ${(winter.totalRadiationDeaths * 1000).toFixed(0)}M radiation`);
   309→    console.log(`   Final temperature: ${(winter.baselineTemperature + winter.temperatureAnomaly).toFixed(1)}°C (baseline: ${winter.baselineTemperature}°C)`);
   310→  }
   311→}
   312→
   313→/**
   314→ * Update radiation zones (decay and mortality)
   315→ */
   316→function updateRadiationZones(state: GameState, winter: NuclearWinterState): void {
   317→  if (winter.radiationZones.length === 0) return;
   318→  
   319→  let totalRadiationDeaths = 0;
   320→  
   321→  winter.radiationZones.forEach(zone => {
   322→    // Decay radiation over time
   323→    zone.currentLevel = zone.currentLevel * (1 - zone.decayRate);
   324→    
   325→    // Apply radiation mortality (scales with radiation level)
   326→    const radiationMortality = zone.monthlyDeathRate * zone.currentLevel;
   327→    
   328→    // Apply to country if we have country tracking
   329→    if (state.countryPopulationSystem) {
   330→      const country = state.countryPopulationSystem.countries[zone.country];
   331→      if (country && country.population > 0.1) {  // Only if country has >100K people
   332→        const countryDeaths = (country.population / 1000) * radiationMortality;  // Convert to billions
   333→        totalRadiationDeaths += countryDeaths;
   334→        
   335→        // Log significant radiation deaths annually
   336→        const monthsSinceHit = state.currentMonth - zone.hitMonth;
   337→        if (monthsSinceHit % 12 === 0 && countryDeaths > 0.001) {
   338→          console.log(`   ☢️  Radiation deaths in ${zone.country}: ${(countryDeaths * 1000).toFixed(1)}M (level: ${(zone.currentLevel * 100).toFixed(0)}%)`);
   339→        }
   340→      }
   341→    }
   342→  });
