      dampingFeedbackStrength?: number;
      recoveryTimescale?: number;
    };
    coral: {
      healthPercentage: number;
      tippingThreshold: number;
      triggered: boolean;
      triggeredAt: number;
      collapseProgress: number;
      fisheryCollapseLevel: number;
