export function getWetBulbThreshold(wetBulbTemp: number): WetBulbThreshold | null {
  if (wetBulbTemp >= WET_BULB_CONSTANTS.EXTREME_THRESHOLD) {
    return {
      temperature: WET_BULB_CONSTANTS.EXTREME_THRESHOLD,
      severity: 'extreme',
