  const povertyEffect = regionalClimate.povertyFraction * 0.7;     // Up to +0.35 (50% poverty → +35%)
  const workerEffect = regionalClimate.outdoorWorkerFraction * 0.4; // Up to +0.16 (40% workers → +16%)

