      },
      // Cooperative Spirals (Oct 17, 2025)
      institutionalResilience: 0.5,  // Moderate baseline institutional resilience
      policyEffectivenessMultiplier: 1.0  // Baseline (no boost from cooperative spirals yet)
    },

    society: {
