    if (value === 0) return '0.0'; // This category has no deaths
    return ((value / total) * 100).toFixed(1);
  };

  console.log('\n=== DEATH SUMMARY BY CATEGORY ===');
  console.log(`Total crisis deaths: ${(pop.cumulativeCrisisDeaths * 1000).toFixed(1)}M`);
  console.log(`Population decline: ${((pop.peakPopulation - pop.population) * 1000).toFixed(1)}M (${(((pop.peakPopulation - pop.population) / pop.peakPopulation) * 100).toFixed(1)}%)`);
  console.log('\nDeaths by Category:');
  console.log(`  War:        ${(deaths.war * 1000).toFixed(1)}M (${formatPercent(deaths.war, totalDeaths)}%)`);
  console.log(`  Famine:     ${(deaths.famine * 1000).toFixed(1)}M (${formatPercent(deaths.famine, totalDeaths)}%)`);
  console.log(`  Climate:    ${(deaths.climate * 1000).toFixed(1)}M (${formatPercent(deaths.climate, totalDeaths)}%)`);
  console.log(`  Disease:    ${(deaths.disease * 1000).toFixed(1)}M (${formatPercent(deaths.disease, totalDeaths)}%)`);
  console.log(`  Ecosystem:  ${(deaths.ecosystem * 1000).toFixed(1)}M (${formatPercent(deaths.ecosystem, totalDeaths)}%)`);
  console.log(`  Pollution:  ${(deaths.pollution * 1000).toFixed(1)}M (${formatPercent(deaths.pollution, totalDeaths)}%)`);
  console.log(`  AI:         ${(deaths.ai * 1000).toFixed(1)}M (${formatPercent(deaths.ai, totalDeaths)}%)`);
  console.log(`  Other:      ${(deaths.other * 1000).toFixed(1)}M (${formatPercent(deaths.other, totalDeaths)}%)`);
  console.log('================================\n');
}

