if (famineDeaths > 0) {
  state.humanPopulationSystem.population -= famineDeaths;

  // MULTI-DIMENSIONAL TRACKING (Oct 18, 2025)
  // PROXIMATE: Famine (starvation, malnutrition)
  state.humanPopulationSystem.deathsByCategory.famine += famineDeaths;

