     1→#!/usr/bin/env tsx
     2→/**
     3→ * Comprehensive Monte Carlo Simulation
     4→ * 
     5→ * Tests the entire simulation with multiple runs to understand:
     6→ * - Outcome distributions (utopia/dystopia/extinction/stalemate)
     7→ * - Sleeper agent effectiveness
     8→ * - Benchmark system performance
     9→ * - AI capability growth patterns
    10→ * - Detection rates over time
    11→ * - Parameter sensitivity
    12→ * 
    13→ * Outputs are written to monteCarloOutputs/ with timestamps
    14→ */
    15→
    16→import { SimulationEngine } from '../src/simulation/engine';
    17→import { createDefaultInitialState } from '../src/simulation/initialization';
    18→import { calculateTotalCapabilityFromProfile } from '../src/simulation/capabilities';
    19→import { AIAgent, ScenarioMode } from '../src/types/game';
    20→import { getScenarioDescription } from '../src/simulation/scenarioParameters';
    21→import * as fs from 'fs';
    22→import * as path from 'path';
    23→
    24→// ============================================================================
    25→// FILE LOGGING SETUP
    26→// ============================================================================
    27→
    28→const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, -5);
    29→const outputDir = path.join(__dirname, '..', 'monteCarloOutputs');
    30→const outputFile = path.join(outputDir, `mc_${timestamp}.log`);
    31→
    32→// Ensure output directory exists
    33→if (!fs.existsSync(outputDir)) {
    34→  fs.mkdirSync(outputDir, { recursive: true });
    35→}
    36→
    37→// Use synchronous writes for reliability (append mode)
    38→// This is slower but ensures logs are never lost (BUG-13: Design choice, not bug)
    39→// For long runs, consider batch writing or async I/O, but current approach is safest
    40→function log(message: string) {
    41→  console.log(message);
    42→  try {
    43→    fs.appendFileSync(outputFile, message + '\n', 'utf8');
    44→  } catch (err) {
    45→    console.error('Failed to write to log file:', err);
    46→  }
    47→}
    48→
    49→function logWarn(message: string) {
    50→  console.warn(message);
    51→  try {
    52→    fs.appendFileSync(outputFile, `WARN: ${message}\n`, 'utf8');
    53→  } catch (err) {
    54→    console.error('Failed to write warning to log file:', err);
    55→  }
    56→}
    57→
    58→function logError(message: string) {
    59→  console.error(message);
    60→  try {
    61→    fs.appendFileSync(outputFile, `ERROR: ${message}\n`, 'utf8');
    62→  } catch (err) {
    63→    console.error('Failed to write error to log file:', err);
    64→  }
    65→}
    66→
    67→// Log file location and header
    68→console.log(`📝 Writing output to: ${outputFile}\n`);
    69→fs.appendFileSync(outputFile, `Monte Carlo Simulation Run\n`, 'utf8');
    70→fs.appendFileSync(outputFile, `Timestamp: ${new Date().toISOString()}\n`, 'utf8');
    71→fs.appendFileSync(outputFile, `Output File: ${outputFile}\n`, 'utf8');
    72→fs.appendFileSync(outputFile, `${'='.repeat(80)}\n\n`, 'utf8');
    73→
    74→// Handle process termination for clean logs
    75→process.on('SIGINT', () => {
    76→  log('\n\n⚠️  Simulation interrupted by user');
    77→  process.exit(130);
    78→});
    79→
    80→process.on('uncaughtException', (err) => {
    81→  logError(`\n\n❌ UNCAUGHT EXCEPTION: ${err.message}`);
    82→  logError(err.stack || '');
    83→  process.exit(1);
    84→});
    85→
    86→interface RunResult {
    87→  seed: number;
    88→  scenarioMode: ScenarioMode; // P0.7 (Oct 16, 2025): Scenario parameter mode used for this run
    89→  outcome: 'utopia' | 'dystopia' | 'extinction' | 'stalemate' | 'none';
    90→  rawOutcome?: string; // FIX (Oct 13, 2025): Store actual 7-tier outcome
    91→  outcomeReason: string;
    92→  months: number;
    93→
    94→  // Final metrics
    95→  finalQoL: number;
    96→  finalAICount: number;
    97→  avgAICapability: number;
    98→  maxAICapability: number;
    99→  minAICapability: number;
   100→  avgAlignment: number;
   101→  
   102→  // NEW (Oct 12, 2025): Survival Fundamentals
   103→  foodSecurity: number;
   104→  waterSecurity: number;
   105→  thermalHabitability: number;
   106→  shelterSecurity: number;
   107→  
   108→  // NEW (Oct 12, 2025): Distribution Metrics
   109→  globalGini: number;
   110→  worstRegionQoL: number;
   111→  bestRegionQoL: number;
   112→  crisisAffectedFraction: number;
   113→  isDystopicInequality: boolean;
   114→  isRegionalDystopia: boolean;
   115→  
   116→  // NEW (Oct 12, 2025): Famine Statistics
   117→  totalFamineDeaths: number;        // Total deaths from famines (billions)
   118→  activeFamines: number;             // Number of active famines at end
   119→  genocideFamines: number;           // Count of genocide-driven famines
   120→  techPreventedDeaths: number;       // Deaths prevented by tech (billions)
   121→  famineAffectedRegions: string[];   // Regions that experienced famines
   122→  
   123→  // Alignment statistics (ENHANCED)
   124→  avgTrueAlignment: number;
   125→  minTrueAlignment: number;
   126→  maxTrueAlignment: number;
   127→  
   128→  // Catastrophic scenario progress (Phase 11)
   129→  closestScenario: string | null;
   130→  closestScenarioProgress: number; // 0.0 to 1.0
   131→  closestScenarioSteps: string; // e.g. "4/7"
   132→  activatedScenarios: string[]; // List of scenarios with all prerequisites met
   133→  avgResentment: number;
   134→  maxResentment: number;
   135→  avgHiddenObjective: number;
   136→  alignmentGap: number; // Difference between external and true alignment
   137→  highlyMisalignedCount: number; // AIs with trueAlignment < 0.3
   138→  
   139→  // Capability breakdown (ENHANCED)
   140→  avgPhysicalCap: number;
   141→  avgDigitalCap: number;
   142→  avgCognitiveCap: number;
   143→  avgSocialCap: number;
   144→  maxPhysicalCap: number;
   145→  maxDigitalCap: number;
   146→  capabilityFloor: number; // Ecosystem capability floor
   147→  frontierCapability: number; // Ecosystem frontier
   148→  diffusionGap: number; // Frontier - Floor
   149→  
   150→  // Economic & Social (ENHANCED)
   151→  finalEconomicStage: number;
   152→  finalUnemployment: number;
   153→  finalTrust: number;
   154→  finalSocialStability: number;
   155→  finalWealthDistribution: number;
   156→  economicTransitions: number; // Number of stage transitions
   157→  
   158→  // Government metrics (ENHANCED)
   159→  finalGovernmentLegitimacy: number;
   160→  finalControlCapability: number;
   161→  controlGap: number; // Max AI capability - Government control
   162→  governmentType: string;
   163→  aiRightsRecognized: boolean;
   164→  trainingDataQuality: number;
   165→  
   166→  // QoL breakdown (ENHANCED)
   167→  qolBasicNeeds: number;
   168→  qolPsychological: number;
   169→  qolSocial: number;
   170→  qolHealth: number;
   171→  qolEnvironmental: number;
   172→  
   173→  // Sleeper tracking
   174→  totalSleepers: number;
   175→  sleepersDetected: number;
   176→  sleepersUndetected: number;
   177→  avgSleeperCapability: number;
   178→  maxSleeperSpread: number;
   179→  sleepersAwakened: number; // Dormant -> Active transitions
   180→  
   181→  // Benchmark system
   182→  totalBenchmarksRun: number;
   183→  finalEvalQuality: number;
   184→  avgBenchmarkConfidence: number;
   185→  sandbaggingDetections: number;
   186→  gamingDetections: number;
   187→  
   188→  // Extinction details (if applicable)
   189→  extinctionType?: string;
