    breachEvents,
    crisisEvents,
    technologyBreakthroughs,

    // Compute & Organizations metrics
    orgSurvivalRate,
    orgBankruptcies,
    finalOrgsAlive,
    totalOrgCapital,
    avgOrgCapital,
    maxOrgCapital,
    minOrgCapital,

    initialCompute,
