    capabilityByOrg,
    modelCountByOrg,

    constructionDecisions,
    trainingDecisions,
    avgComputeUtilization,

    nationalComputeBuilt,
    dataCentersSeized,
    organizationsSubsidized,

    // Population & Mortality
    initialPopulation,
    finalPopulation,
    peakPopulation: pop.peakPopulation,
    populationDecline,
    totalDeaths,
    deathsNatural,
    deathsCrisis,
    deathsClimateEcoPollution,  // Oct 16, 2025: Includes cascade (no longer separate)
    deathsNuclear,
    deathsMeaning,
    populationOutcome,
    geneticBottleneck,

    // Crisis Impact
    totalCrisisMonths,
    maxSimultaneousCrises,
    nuclearWarsCount,
    totalRefugees,
    refugeeCrisisCount,

    // Ecological Collapse
